WF.storage=function(){const STORAGE_KEY="wf_checklist_progress",VERSION_KEY="wf_checklist_current_version",DELETE=!0;function load(){try{const raw=localStorage.getItem(STORAGE_KEY);return raw?function(progressMap){if(!WF.data||void 0===WF.WCT_VERSION)return progressMap;if(localStorage.getItem(VERSION_KEY)===String(WF.WCT_VERSION))return progressMap;const validKeys=new Set(WF.data.map((item=>item.item_name))),orphanKeys=Object.keys(progressMap).filter((key=>!validKeys.has(key)));return orphanKeys.length>0&&(console.log("Deleted: ",orphanKeys),DELETE&&(orphanKeys.forEach((key=>delete progressMap[key])),localStorage.setItem(STORAGE_KEY,JSON.stringify(progressMap)))),localStorage.setItem(VERSION_KEY,String(WF.WCT_VERSION)),progressMap}(JSON.parse(raw)):{}}catch(err){return console.error("Unreadable or corrupted localStorage progress, reset.",err),{}}}function save(progressMap){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(progressMap)),window.dispatchEvent(new CustomEvent("wf:progress-changed"))}catch(err){console.error("Failed to save progress to localStorage.",err)}}return{load:load,save:save,setOwned:function(itemName,owned){const progress=load();!!progress[itemName]!=!!owned&&(progress[itemName]=owned,save(progress))},setOwnedBulk:function(itemNames,owned){const progress=load();let hasChanged=!1;itemNames.forEach((itemName=>{!!progress[itemName]!=!!owned&&(progress[itemName]=owned,hasChanged=!0)})),hasChanged&&save(progress)},clearAll:function(){try{localStorage.removeItem(STORAGE_KEY),window.dispatchEvent(new CustomEvent("wf:progress-changed"))}catch(err){console.error("Failed to clear progress from localStorage.",err)}},STORAGE_KEY:STORAGE_KEY}}();